mapper.select:
SELECT user_id, COUNT( item_id ) collect_count, SUM( max_collect_price ) AS collect_price FROM ( SELECT user_id, item_id, MAX( collect_price ) AS max_collect_price FROM sw_user_item_collect WHERE deleted = 0 AND collect_price < 2000 GROUP BY user_id, item_id ) AS t GROUP BY user_id
HAVING COUNT( item_id ) = #{itemSize}
ORDER BY collect_price DESC LIMIT 0,20

SELECT user_id, COUNT( item_id ) collect_count, SUM( min_collect_price ) AS collect_price FROM ( SELECT user_id, item_id, MIN( collect_price ) AS min_collect_price FROM sw_user_item_collect WHERE deleted = 0 GROUP BY user_id, item_id ) AS t GROUP BY user_id
HAVING COUNT( item_id ) = #{itemSize}
ORDER BY collect_price ASC LIMIT 0,20
